def assert_historical_protected_hash(root: Path,relative: str,expected: str) -> None:
 relative=relative.replace(chr(92),'/')
 actual=hashlib.sha256((root/relative).read_bytes()).hexdigest()
 row=SUPERSESSIONS.get(relative)
 if row is None:
  assert actual==expected,(relative,'unregistered protected source drift')
  return
 assert expected in row['allowed_historical_sha256'],(relative,'unknown historical source')
 assert actual==row['accepted_current_sha256'],(relative,'approved source drift')
 for reference,digest in row['reference_bindings'].items():
  assert hashlib.sha256((root/reference).read_bytes()).hexdigest()==digest,(relative,reference,'approval binding changed')
 authority=row['authority'];record=json.loads((root/authority['path']).read_text(encoding='utf-8'))
 accepted=record[authority['key']] if authority['kind']=='hash_map' else next(x['sha256'] for x in record if x['filename']==authority['filename'])
 assert accepted==actual,(relative,'accepted authority does not match source')
